import csv
pairs={'up':'/workspace/data/gprofiler_go_only_up.tsv','down':'/workspace/data/gprofiler_go_only_down_retry.tsv'}
for name,path in pairs.items():
    rows=[]
    with open(path) as f:
        for row in csv.DictReader(f, delimiter='\\t'):
            if row.get('source')=='GO:BP':
                rows.append((row['term_id'],row['term_name'],float(row['p_value']),int(row['intersection_size']),int(row['term_size'])))
    rows.sort(key=lambda x:x[2])
    print('\\n',name.upper(),'total GO:BP significant',len(rows))
    mets=[t for t in rows if any(k in t[1].lower() for k in ['metabol','catabolic','biosynthetic','glycolysis','gluconeogenesis','lipid','fatty acid','cholesterol','sterol','ketone','carbohydrate','glucose','amino acid','nucleotide','mitochondri','respiratory','oxidative','redox','energy','atp','acetyl-coa','acyl-coa','pyruvate','hexose','monosaccharide','carboxylic acid','organic acid','oxoacid'])]
    print('metabolic keyword matches',len(mets))
    for t in mets:
        print(f'{t[0]}\\t{t[1]}\\tp={t[2]:.3g}\\tint={t[3]}/{t[4]}')
PY"
